// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D5: transacción bloqueada más de 30 s. Una alerta por sesión bloqueada (PID + hora de inicio).
const filas = $input.all().map(i => i.json).filter(r => r.marca);
return filas.map(r => ({ json: {
  codigo: 'D5',
  severidad: 'ADVERTENCIA',
  tipo: 'Transacción bloqueada (> 30 s)',
  tabla: r.tablas || 'N/A',
  detalle: `${r.marca}: ${r.segundos} s (umbral: 30 s). Bloqueada por: ${r.bloqueadores || 'N/A'}`,
  query: r.query,
  usuario: r.usuario,
  accion: 'Revisar la transacción que bloquea: COMMIT/ROLLBACK, o terminarla con SELECT pg_terminate_backend(<PID>);'
}}));
